def kode_ordinal(nilai, urutan):
    rank = {n: i for i, n in enumerate(urutan)}
    return [rank.get(v, -1) for v in nilai]

from collections import Counter

def modus(data):
    if not data:
        return []
    c = Counter(data)
    m = max(c.values())
    return sorted(k for k, v in c.items() if v == m)

